import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"猫眼效应","description":"","frontmatter":{"title":"猫眼效应","phenomenon":"chatoyancy"},"headers":[],"relativePath":"zh/classification/optical-phenomena/chatoyancy.md","filePath":"zh/classification/optical-phenomena/chatoyancy.md","lastUpdated":1790876393000}'),l={name:"zh/classification/optical-phenomena/chatoyancy.md"};function i(s,e,n,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="猫眼效应" tabindex="-1">猫眼效应 <a class="header-anchor" href="#猫眼效应" aria-label="Permalink to &quot;猫眼效应&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>猫眼效应是当宝石内含大量平行排列的纤维状包裹体、空洞或管状 结构时，弧面切割下垂直于包裹体走向的弧顶呈现一道明亮游动的 光带，类似猫的眼睛。最著名的&quot;金绿猫眼&quot;（cymophane）是该效应 的命名来源。其他如碧玺猫眼、磷灰石猫眼、月光石（虽为不同机 制但视觉相似）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>单向反射：所有包裹体沿同一方向延展（如金绿宝石中沿 c 轴的 空管）。从顶部观察，每根管子都把垂直方向的光反射到眼睛中。 整个包裹体群反射的光被几何约束成一道垂直于走向的窄光带。包 括包裹体越多、越细、越平行，效果越强。</p><h2 id="示例宝石" tabindex="-1">示例宝石 <a class="header-anchor" href="#示例宝石" aria-label="Permalink to &quot;示例宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>包裹体形态</th><th>宿主矿物</th></tr></thead><tbody><tr><td>Chrysoberyl Cat&#39;s-eye / 金绿猫眼</td><td>hollow tubes along c-axis</td><td>Chrysoberyl</td></tr><tr><td>Tourmaline Cat&#39;s-eye / 碧玺猫眼</td><td>parallel hollow channels</td><td>Elbaite</td></tr><tr><td>Apatite Cat&#39;s-eye / 磷灰石猫眼</td><td>fibrous inclusions</td><td>Apatite</td></tr><tr><td>Hawk&#39;s-eye / 鹰眼石</td><td>crocidolite fibers</td><td>Quartz (pseudomorph)</td></tr><tr><td>Tiger&#39;s-eye / 虎眼石</td><td>crocidolite fibers (oxidized)</td><td>Quartz (pseudomorph)</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA：现象宝石指南</a><span>光学现象的观察方式与宝石学语境</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA：现象弧面宝石的光学效应</a><span>弧面切割、光源、角度与光学表现</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">光学现象总览</a>。</em></p>',9)])])}const f=t(l,[["render",i]]);export{m as __pageData,f as default};
